    import { mapState, mapMutations } from 'vuex'
	// import theme from "@/mixins/theme";
    export default {
        name: 'home_userInfor',
        cname: '用户信息',
        configName: 'c_userInfor',
        icon: '#iconzujian-yonghuxinxi',
        type:0,// 0 基础组件 1 营销组件 2工具组件
        defaultName:'userInfor', // 外面匹配名称
        props: {
            index: {
                type: null
            },
            num: {
                type: null
            },
			colorStyle:{
				type: null
			}
        },
        computed: {
            ...mapState('admin/mobildConfig', ['defaultArray'])
        },
        watch: {
            pageData: {
                handler (nVal, oVal) {
                    this.setConfig(nVal)
                },
                deep: true
            },
            num: {
                handler (nVal, oVal) {
                    let data = this.$store.state.admin.mobildConfig.defaultArray[nVal]
                    this.setConfig(data)
                },
                deep: true
            },
            'defaultArray': {
                handler (nVal, oVal) {
                    let data = this.$store.state.admin.mobildConfig.defaultArray[this.num]
                    this.setConfig(data);
                },
                deep: true
            }
        },
        // mixins: [theme],
		data () {
            return {
                // 默认初始化数据禁止修改
                defaultConfig: {
					cname: '用户信息',
                    name: 'userInfor',
                    timestamp: this.num,
					isHide:false,
                    setUp: {
                        tabVal: 0
                    },
					titleLeft:'展示设置',
					titleImg:'默认头像',
					titleRight:'进度条',
					titleCurrency:'通用样式',
					styleConfig:{
						title: '选择风格',
						tabVal: 1,
						tabList: [
							{
							  name: '样式一'
							},
						    {
						      name: '样式二'
						    }
						]
					},
                    checkboxInfo: {
                        title: '是否展示',
                        name: 'checkboxInfo',
						userType:1,
                        type:[3,1,2],
                        list: [
							{
							    id:3,
							    name:'会员码'
							},
							{
							    id:1,
							    name:'积分'
							},
							{
							    id:2,
							    name:'余额'
							},
							{
							    id:4,
							    name:'收藏'
							},
                            {
                                id:0,
                                name:'优惠券'
                            },
							{
							    id:5,
							    name:'浏览'
							}
                        ]
                    },
					logoConfig:{
						info: '建议：图片尺寸90px * 90px',
						url: '',
						type:'code',
						delType:1,
						name:'上传图片'
					},
					toneConfig:{
						title: '色调',
						tabVal: 0,
						tabList: [
							{
							  name: '跟随主题风格'
							},
						    {
						      name: '自定义'
						    }
						]
					},
					progressColor: {
					    title: '进度条',
					    default: [
					        {
					           item: '#e93323'
					        },
					        {
					           item: '#ff8933'
					        }
					    ],
					    color: [
					        {
					            item: '#e93323'
					        },
					        {
					            item: '#ff8933'
					        }
					    ]
					},
					progressBgColor:{
						title: '进度条背景',
						default: [
						    {
						       item: '#EEEEEE'
						    }
						],
						color: [
						    {
						        item: '#EEEEEE'
						    }
						]
					},
					moduleColor:{
						title: '组件背景',
						default: [
						    {
						       item: '#fff'
						    },
							{
							   item: '#fff'
							}
						],
						color: [
						    {
						        item: '#fff'
						    },
							{
							   item: '#fff'
							}
						]
					},
					bottomBgColor:{
						title: '底部背景',
						default: [
						    {
						       item: '#fff'
						    }
						],
						color: [
						    {
						        item: '#fff'
						    }
						]
					},
					topConfig: {
						title: '上边距',
						val: 0,
						min: 0
					},
					bottomConfig: {
						title: '下边距',
						val: 0,
						min: 0
					},
					prConfig: {
					    title: '左右边距',
					    val: 0,
					    min: 0
					},
					mbConfig: {
					    title: '页面间距',
					    val: 0,
					    min: 0
					},
					fillet:{
						title:'背景圆角',
						type: 0,
						list: [
						  {
						    val: "全部",
						    icon: "iconcaozuo-zhengti",
						  },
						  {
						    val: "单个",
						    icon: "iconcaozuo-bianjiao",
						  }
						],
						valName:'圆角值',
						val: 0,
						min: 0,
						valList:[
							{val:0},
							{val:0},
							{val:0},
							{val:0}
						]
					}
                },
				pageData: {},
				styleConfig:0,
				checkType:[],
				logoConfig:'',
				progressLeft:'',
				progressRight:'',
				progressBgColor:'',
				bgColorLeft:'',
				bgColorRight:'',
				bottomBgColor:'',
				topConfig:0,
				bottomConfig:0,
				prConfig:0,
                mTop: '',
				bgRadius:0,
				toneConfig:0,
				themeColor:''
            }
        },
        mounted () {
            this.$nextTick(() => {
                this.pageData = this.$store.state.admin.mobildConfig.defaultArray[this.num]
                this.setConfig(this.pageData);
            })
        },
        methods: {
            setConfig (data) {
                if(!data) return
                if(data.mbConfig){
					this.styleConfig = data.styleConfig.tabVal;
					this.checkType = data.checkboxInfo.type;
					this.logoConfig = data.logoConfig.url;
					this.toneConfig = data.toneConfig.tabVal;
					this.progressLeft = data.progressColor.color[0].item;
					this.progressRight = data.progressColor.color[1].item;
					this.progressBgColor = data.progressBgColor.color[0].item;
					this.bgColorLeft = data.moduleColor.color[0].item;
					this.bgColorRight = data.moduleColor.color[1].item;
					this.themeColor = `linear-gradient(90deg,${this.colorStyle.theme} 0%,${this.colorStyle.gradient} 100%)`;
					this.bottomBgColor = data.bottomBgColor.color[0].item;
					this.topConfig = data.topConfig.val;
					this.bottomConfig = data.bottomConfig.val;
					this.prConfig = data.prConfig.val;
                    this.mTop = data.mbConfig.val;
                    let fillet = data.fillet.type;
                    let filletVal = data.fillet.val
                    let valList = data.fillet.valList;
                    this.bgRadius = fillet? valList[0].val+ 'px ' +valList[1].val + 'px ' + valList[3].val + 'px ' + valList[2].val +'px' : filletVal +'px';
                }
            }
        }
    }
